#include <string>
#include <vector>
#include <algorithm>
#include <cmath>
#include <iostream>
#include <array>
#include <queue>
#include <stack>
#define ALL(x) x.begin(),x.end()
using namespace std;
typedef long long ll;
int n,m,k,res,nowx,nowy;
bool xd=true;
int main(){
	cin >> n >> m >> k;
    while(k--){
        res+=!(nowx&nowy);
        if(nowy==m-1 && m%2!=nowx%2){
            nowx++;
            xd=!xd;
        }else if(nowx==n-1 && n%2==nowy%2){
            nowy++;
            xd=!xd;
        }else if(nowx==0 && nowy%2==0){
            nowy++;
            xd=!xd;
        }else if(nowy==0 && (nowx&1)){
            nowx++;
            xd=!xd;
        }else{
            if(xd){
                nowy++;
                nowx--;
            }else{
                nowx++;
                nowy--;
            }
        }
    }
    cout << res;
}
